 X=list(itertools.product(P,Q)); N=len(X)
 le=lambda x,y:(x[0]&y[0]==x[0] and x[1]&y[1]==x[1])
 down=[{i for i in range(N) if i!=j and le(X[i],X[j])} for j in range(N)]
 up=[{i for i in range(N) if i!=j and le(X[j],X[i])} for j in range(N)]
